"""Capture only responses generated by ordinary match-page browsing.

This experiment imports existing pure parsers/storage helpers but never calls
the existing BrowserClient or changes its component cache or access latch.
"""
from __future__ import annotations

import base64
from collections import Counter
from contextlib import ExitStack
from datetime import datetime, timezone
import json
import math
from pathlib import Path
import re
import sqlite3
import time
from urllib.parse import urlsplit
import uuid

from scraping.sofascore.config import Profile, Scope
from scraping.sofascore.event_round import match_round, match_season
from scraping.sofascore.export import normalize_store, publish_tables
from scraping.sofascore.models import CollectionPaused, Job
from scraping.sofascore.parsers import validate_payload
from scraping.sofascore.planner import component_jobs
from scraping.sofascore.rate_limit import retry_after_seconds
from scraping.sofascore.store import Store, atomic_write, json_bytes, season_year_pair

ROOT = Path(__file__).resolve().parents[2]
PROFILE = Profile(include_goal_actions=True, include_lineups=True, include_comments=False,
                  duration_mode="incidents")
API_HOSTS = {"www.sofascore.com", "api.sofascore.com"}


def api_path(url):
    parsed = urlsplit(url)
    if parsed.scheme == "https" and parsed.hostname in API_HOSTS and parsed.path.startswith("/api/v1/"):
        return parsed.path[len("/api/v1"):]
    return None


def match_url(event):
    slug, custom = event.get("slug"), event.get("customId")
    if not isinstance(slug,str) or not re.fullmatch(r"[a-z0-9-]+",slug):
        raise ValueError("Reference event needs a provider match slug")
    if not isinstance(custom,str) or not re.fullmatch(r"[A-Za-z0-9]+",custom):
        raise ValueError("Reference event needs a provider customId")
    return f"https://www.sofascore.com/football/match/{slug}/{custom}#id:{int(event['id'])}"


def reference_from_cache(event_id, cache_root=None):
    """Read fixture identity only; never import old component values as new captures."""
    path = Path(cache_root or ROOT/"data/collection_state")/"manifest.sqlite"
    with sqlite3.connect(path.resolve().as_uri()+"?mode=ro", uri=True) as db:
        row = db.execute("SELECT payload,observed FROM events WHERE event_id=?", (event_id,)).fetchone()
    if row is None:
        raise ValueError(f"Event {event_id} is not in the existing fixture cache")
    return {"event":json.loads(row[0]), "observed_at":row[1],
            "source":str(path.resolve()), "note":"Identity reference only; no components imported"}


class WebsiteCapture:
    """One bounded, visible browser experiment for one reference match.

    Browser-generated bursts cannot be paced individually. Limits stop browsing
    when observed and can overshoot during a burst. No URL replay or fetch/XHR
    injection is used. The shared ledger is locked throughout the experiment.
    """
    def __init__(self, reference, *, output_root=None, ledger_root=None, driver_path=None,
                 max_api_requests=80, max_seconds=600, driver_factory=None, profile=PROFILE):
        if (isinstance(max_api_requests,bool) or not isinstance(max_api_requests,int) or
                max_api_requests < 1 or isinstance(max_seconds,bool) or
                not math.isfinite(max_seconds) or not 1 <= max_seconds <= 3600):
            raise ValueError("Use a positive request limit and 1–3600 seconds")
        if profile.include_comments:
            raise ValueError("This experiment does not retain commentary")
        if reference["event"].get("status",{}).get("type") != "finished":
            raise ValueError("Select a completed reference match")
        self.profile = profile
        self.reference = reference
        self.event = reference["event"]
        self.url = match_url(self.event)
        years = season_year_pair(match_season(self.event)["year"])
        if years is None:
            raise ValueError("Reference match needs an unambiguous season year pair")
        self.scope = Scope(self.event["tournament"]["uniqueTournament"]["id"],
                           match_season(self.event)["id"],(match_round(self.event),),
                           season_start=years[0],season_end=years[1])
        self.jobs = {job.path:job for job in component_jobs(self.event,profile,time.time())}
        self.event_job = Job(f"/event/{self.event['id']}","event",self.event["id"])
        self.jobs[self.event_job.path] = self.event_job
        stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
        self.directory = Path(output_root or ROOT/"data/website_capture_v3") / f"{stamp}-{uuid.uuid4().hex[:8]}"
        self.ledger_root = Path(ledger_root or ROOT/"data/collection_state")
        self.driver_path = driver_path
        self.driver_factory = driver_factory
        self.max_api_requests, self.max_seconds = max_api_requests, max_seconds
        self.stack = ExitStack()
        self.driver = None
        self.requests = []
        self.by_id = {}
        self.hosts = Counter()
        self.total_requests = 0
        self.actions = []
        self.ui_elements = []
        self.stop_reason = None
        self.closed = False
        self.started = None
        self.event_metadata_source = "reference_from_existing_cache"
        self.page_url = None
        self.page_event_id = None
        self.match_opened = False
        self.challenge_warmup = False

    def start(self):
        if self.started is not None:
            raise RuntimeError("This capture session has already started")
        self.directory.mkdir(parents=True)
        try:
            self.ledger = self.stack.enter_context(Store(self.ledger_root))
            self.stack.enter_context(self.ledger.run_lock())
            if self.ledger.setting("cooldown_until",0)>time.time():
                raise CollectionPaused("The shared provider cooldown is still active")
            self.saved_access_block = self.ledger.setting("access_block")
            self.store = self.stack.enter_context(Store(self.directory/"captured"))
            # Reference metadata supplies stable joins and is explicitly labelled.
            # Component values are never imported from the old cache.
            self.store.add_events([self.event],self.scope,self.event_job,self.reference["observed_at"])
            atomic_write(self.directory/"reference.json",json_bytes(self.reference))
            self.started = time.time()
            self.run_id = self.ledger.start_run()
            if self.driver_factory:
                self.driver = self.driver_factory()
            else:
                from selenium import webdriver
                from selenium.webdriver.chrome.service import Service
                options = webdriver.ChromeOptions()
                options.page_load_strategy = "eager"
                options.set_capability("goog:loggingPrefs",{"performance":"ALL"})
                options.add_experimental_option("prefs",{"intl.accept_languages":"en"})
                service = Service(executable_path=str(self.driver_path)) if self.driver_path else Service()
                self.driver = webdriver.Chrome(service=service,options=options)
                self.driver.set_page_load_timeout(30)
                self.driver.execute_cdp_cmd("Network.enable",{
                    "maxTotalBufferSize":64000000,"maxResourceBufferSize":8000000})
            self.checkpoint()
            return self
        except BaseException:
            self.close()
            raise

    def open_match(self):
        self._can_browse()
        self.match_opened = True
        self.challenge_warmup = False
        self.actions.append({"action":"open_match","at":time.time(),"url":self.url})
        self._navigate(self.url)

    def open_homepage(self):
        """Optional bounded human challenge step before opening the selected match."""
        self._can_browse()
        if self.match_opened:
            raise RuntimeError("Challenge warmup must precede the match experiment")
        self.challenge_warmup = True
        self.actions.append({"action":"open_homepage","at":time.time()})
        self._navigate("https://www.sofascore.com/")

    def _navigate(self, url):
        from selenium.common.exceptions import TimeoutException
        try:
            self.driver.get(url)
        except TimeoutException:
            self.actions.append({"action":"page_load_timeout","at":time.time()})
        self.poll()

    def _can_browse(self):
        if self.closed or self.driver is None:
            raise RuntimeError("Capture browser is not running")
        if self.stop_reason:
            raise CollectionPaused(self.stop_reason)
        if self.ledger.setting("cooldown_until",0)>time.time():
            raise CollectionPaused("The shared provider cooldown is active")

    def poll(self):
        if self.closed or self.driver is None:
            return
        from selenium.common.exceptions import WebDriverException
        activity = False
        try:
            logs = self.driver.get_log("performance")
        except WebDriverException as exc:
            self.stop_reason = self.stop_reason or "browser_unavailable"
            self.actions.append({"action":"browser_unavailable","error_type":type(exc).__name__,"at":time.time()})
            self.checkpoint()
            return
        for item in logs:
            message = json.loads(item["message"])["message"]
            method, params = message.get("method"), message.get("params",{})
            request_id = params.get("requestId")
            if method == "Network.requestWillBeSent":
                url = params.get("request",{}).get("url","")
                self.total_requests += 1
                self.hosts[urlsplit(url).hostname or "local"] += 1
                path = api_path(url)
                if path is None:
                    continue
                activity = True
                # Redirects are separate observed requests, even with the same ID.
                if request_id in self.by_id and params.get("redirectResponse"):
                    self._response(self.by_id[request_id],params["redirectResponse"])
                record = {"request_id":request_id,"path":path,"at":time.time(),
                          "status":None,"resource_type":params.get("type"),"capture":"pending",
                          "method":params.get("request",{}).get("method","GET"),
                          "query_present":bool(urlsplit(url).query),"body_bytes":0}
                with self.ledger.db:
                    cursor = self.ledger.db.execute(
                        "INSERT INTO attempts(run_id,key,started,outcome) VALUES (?,?,?,?)",
                        (self.run_id,"website_capture_v3|"+path,record["at"],"website_observed"))
                record["ledger_attempt"] = cursor.lastrowid
                self.requests.append(record)
                self.by_id[request_id] = record
            elif request_id in self.by_id:
                activity = True
                record = self.by_id[request_id]
                if method == "Network.responseReceived":
                    self._response(record,params["response"])
                elif method == "Network.loadingFinished":
                    record["encoded_bytes"] = params.get("encodedDataLength")
                    self._capture_body(record)
                elif method == "Network.loadingFailed":
                    record["capture"] = "network_failed"
                    job = self._target_job(record)
                    if job:
                        self.store.record(job,"failed",time.time(),error="network_failed")
                elif method == "Network.requestServedFromCache":
                    record["from_cache"] = True
        if activity:
            self.ledger.set_setting("last_request_finished",time.time())
        if not getattr(self,"stopped_page",False):
            self.page_url = self.driver.current_url
            fragment = re.search(r"(?:^|[,&;])id:(\d+)(?:$|[,&;])",urlsplit(self.page_url).fragment)
            self.page_event_id = int(fragment.group(1)) if fragment else None
            if self.match_opened and self.page_event_id not in (None,self.reference["event"]["id"]):
                self.stop_reason = self.stop_reason or "event_identity_mismatch"
        if self.stop_reason is None and len(self.requests)>=self.max_api_requests:
            self.stop_reason = "observed_api_request_limit"
        if self.stop_reason is None and time.time()-self.started>=self.max_seconds:
            self.stop_reason = "session_time_limit"
        if self.stop_reason and not getattr(self,"stopped_page",False):
            self.stopped_page = True
            try:
                self.driver.save_screenshot(str(self.directory/"stopped-page.png"))
                self.driver.get("about:blank")
            except WebDriverException:
                pass
        self.checkpoint()

    def _response(self,record,response):
        record["status"] = int(response["status"])
        record["mime"] = response.get("mimeType")
        record["from_cache"] = bool(record.get("from_cache") or response.get("fromDiskCache") or response.get("fromPrefetchCache") or
                                     response.get("fromServiceWorker"))
        headers = {key.lower():str(value) for key,value in response.get("headers",{}).items()}
        with self.ledger.db:
            self.ledger.db.execute("UPDATE attempts SET status=? WHERE id=?",(record["status"],record["ledger_attempt"]))
        delay = retry_after_seconds(headers.get("retry-after"),time.time())
        if record["status"]==429 and delay is None:
            delay = 3600
        if delay is not None and delay>0:
            self.ledger.set_setting("cooldown_until",max(self.ledger.setting("cooldown_until",0),time.time()+delay))
            self.stop_reason = "provider_cooldown"
        # During the optional human warmup, leave the challenge page visible.
        # Once match browsing starts, access denial ends this bounded attempt.
        if record["status"] in {401,403} and not self.challenge_warmup:
            self.stop_reason = self.stop_reason or "access_denied"
        job = self._target_job(record)
        if job and record["status"] >= 400:
            state = ("unavailable" if record["status"]==404 else "rate_limited" if record["status"]==429
                     else "blocked" if record["status"] in {401,403} else "failed")
            record["capture"] = state
            self.store.record(job,state,time.time(),http_status=record["status"])

    def _target_job(self, record):
        if record["query_present"] or record["method"] != "GET":
            return None
        return self.jobs.get(record["path"])

    def _capture_body(self,record):
        from selenium.common.exceptions import WebDriverException
        if record["status"] != 200 or record.get("body_processed"):
            return
        record["body_processed"] = True
        job = self._target_job(record)
        if job is None:
            record["capture"] = "variant_not_normalized" if record["path"] in self.jobs else "not_targeted"
            return
        try:
            response = self.driver.execute_cdp_cmd("Network.getResponseBody",{"requestId":record["request_id"]})
            body = base64.b64decode(response["body"]).decode() if response.get("base64Encoded") else response["body"]
            record["body_bytes"] = len(body.encode())
            payload = json.loads(body)
            empty = validate_payload(job.component,payload)
            if job.component=="event":
                if payload["event"]["id"] != self.event["id"]:
                    raise ValueError("Response event ID disagrees with the selected match")
                for side in ("homeTeam","awayTeam"):
                    if payload["event"].get(side,{}).get("id") != self.reference["event"][side]["id"]:
                        raise ValueError("Response teams disagree with the reference match")
                if payload["event"].get("status",{}).get("type") != "finished":
                    raise ValueError("Response is not a completed match")
                self.store.add_events([payload["event"]],self.scope,job,time.time())
                self.event = payload["event"]
                self.event_metadata_source = "captured_website_response"
            self.store.record(job,"empty" if empty else "success",time.time(),payload=payload,
                              http_status=200,event_context=self.event)
            record["capture"] = "saved"
            record["raw_hash"] = self.store.get(job)["raw_hash"]
        except (WebDriverException,ValueError,TypeError,KeyError,UnicodeError) as exc:
            record["capture"] = "body_or_schema_error"
            record["error_type"] = type(exc).__name__
            self.store.record(job,"failed",time.time(),http_status=200,error=type(exc).__name__)

    def observe(self,seconds=8):
        if not math.isfinite(seconds) or seconds < 0:
            raise ValueError("Observation seconds must be finite and nonnegative")
        until = time.monotonic()+seconds
        while time.monotonic()<until and not self.stop_reason:
            self.poll()
            time.sleep(.25)
        self.poll()
        return self.report()

    def snapshot(self):
        from selenium.webdriver.common.by import By
        self.poll()
        elements=[]
        self.ui_elements=[]
        for element in self.driver.find_elements(By.CSS_SELECTOR,"button,a,[role='tab'],[role='button']"):
            if not element.is_displayed():
                continue
            label=(element.text or element.get_attribute("aria-label") or "").strip()
            if not label:
                continue
            self.ui_elements.append(element)
            elements.append({"index":len(self.ui_elements)-1,"tag":element.tag_name,
                             "role":element.get_attribute("role"),"label":label[:180]})
        stamp=len(list(self.directory.glob("screen-*.png")))+1
        screenshot=self.directory/f"screen-{stamp:02d}.png"
        self.driver.save_screenshot(str(screenshot))
        result={"url":self.driver.current_url,"title":self.driver.title,"elements":elements[:200],
                "text":self.driver.find_element(By.TAG_NAME,"body").text[:10000],"screenshot":str(screenshot)}
        atomic_write(self.directory/f"screen-{stamp:02d}.json",json_bytes(result))
        return result

    def click(self,index):
        self._can_browse()
        if not 0<=index<len(self.ui_elements):
            raise ValueError("Choose an element index from the latest snapshot")
        element=self.ui_elements[index]
        self.actions.append({"action":"click","at":time.time(),"label":element.text[:180]})
        element.click()
        self.ui_elements=[]

    def report(self):
        if self.closed and hasattr(self,"final_report"):
            return self.final_report
        coverage=[]
        for path,job in self.jobs.items():
            state=self.store.get(job)
            coverage.append({"path":path,"component":job.component,"team_id":job.team_id,
                             "status":state["status"] if state else "not_observed",
                             "raw_hash":state["raw_hash"] if state else None})
        target_requests=sum(self._target_job(record) is not None for record in self.requests)
        return {"experiment":"sofascore_web_v3","event_id":self.event["id"],"match_url":self.url,
                "directory":str(self.directory),"started_at":self.started,"closed":self.closed,
                "stop_reason":self.stop_reason,"total_browser_requests":self.total_requests,
                "page_url":self.page_url,"page_event_id":self.page_event_id,
                "page_identity_matches":self.page_event_id==self.reference["event"]["id"],
                "observed_api_requests":len(self.requests),"target_api_requests":target_requests,
                "other_api_requests":len(self.requests)-target_requests,
                "duplicate_api_requests":len(self.requests)-len({r["path"] for r in self.requests}),
                "direct_api_requests_by_collector":0,"hosts":dict(self.hosts),
                "browser_cache_responses":sum(bool(r.get("from_cache")) for r in self.requests),
                "http_status_counts":dict(Counter(str(r["status"]) for r in self.requests)),
                "event_metadata_source":self.event_metadata_source,"coverage":coverage,"actions":self.actions,
                "direct_component_request_baseline":len(self.jobs)-1,
                "comparison_note":"Baseline counts selected components once, excluding discovery, metadata refreshes and retries. Observed website requests include cache hits, unrelated calls and repeated loads; query variants are grouped by path in duplicate counts.",
                "limit_note":"Limits stop the page after traffic is observed; browser bursts can overshoot. Old collector access block remains unchanged."}

    def checkpoint(self):
        if self.started is None:
            return
        if time.monotonic()-getattr(self,"last_checkpoint",0)<1:
            return
        self.last_checkpoint=time.monotonic()
        atomic_write(self.directory/"requests.json",json_bytes(self.requests))
        atomic_write(self.directory/"report.json",json_bytes(self.report()))

    def finish(self):
        if self.closed:
            return json.loads((self.directory/"report.json").read_text())
        try:
            self.poll()
            tables=normalize_store(self.store,self.scope,self.profile)
            # The imported reference is not proof of a successful live metadata load.
            metadata_state=self.store.get(self.event_job)
            tables.setdefault("coverage",[]).append({"event_id":self.event["id"],"component":"event",
                "status":metadata_state["status"] if metadata_state else "pending",
                "latest_attempt_status":metadata_state["status"] if metadata_state else "pending"})
            report=self.report()
            complete=(self.stop_reason is None and self.event_metadata_source=="captured_website_response"
                      and metadata_state is not None and metadata_state["status"]=="success"
                      and self.page_event_id==self.event["id"]
                      and all(row["status"] in {"success","empty","unavailable"} for row in report["coverage"]))
            manifest=publish_tables(tables,self.directory/"prepared",scope=self.scope,profile=self.profile,
                provenance={"artifact_kind":"single_match_website_experiment","selected_event_id":self.event["id"],
                            "event_metadata_source":self.event_metadata_source,"reference_file":"reference.json",
                            "live_capture_complete":complete,
                            "component_source":"website_generated_responses_only"})
            report.update(manifest=str(manifest),table_rows={name:len(rows) for name,rows in tables.items()},
                          complete=complete)
            self.final_report=report
        finally:
            self.close()
        return self.final_report

    def close(self):
        if self.closed:
            return
        if self.driver is not None:
            try:
                self.driver.quit()
            except Exception as exc:
                self.cleanup_error=type(exc).__name__
            finally:
                self.driver=None
        self.closed=True
        try:
            if self.started is not None:
                report=self.final_report if hasattr(self,"final_report") else self.report()
                report["closed"]=True
                if not hasattr(self,"final_report"):
                    report["complete"]=False
                if hasattr(self,"cleanup_error"):
                    report["cleanup_error"]=self.cleanup_error
                self.final_report=report
                atomic_write(self.directory/"requests.json",json_bytes(self.requests))
                atomic_write(self.directory/"report.json",json_bytes(report))
                if hasattr(self,"run_id"):
                    self.ledger.finish_run(self.run_id,"complete" if report.get("complete") else "incomplete",report)
        finally:
            self.stack.close()
